ssr.probe:
//! Temporary ablation probe: real Analysis query, explicit project, all edits hashed.
use std::{collections::{HashMap,HashSet},hash::{Hash,Hasher},time::Instant};
use base_db::{FileId,module_graph::{ModuleData,ModuleGraph},preprocess::SourceProject};
use ide::analysis::{Analysis,AnalysisHost,UrlMap};
fn main() {
 let mut host=AnalysisHost::new();
 let mut change=ide_db::apply_change::Change::new();
 let mut urls=HashMap::new(); let mut paths=Vec::new(); let mut ids=Vec::new();
 for n in 0..10 {
  let id=FileId::from_raw(n); ids.push(id);
  let path=std::path::PathBuf::from(format!("/ssr-probe/f{n}.sail"));
  urls.insert(url::Url::from_file_path(&path).unwrap(),id); paths.push((path,id));
  let mut text=if n==0 {"val combine : (int, int) -> int\nval flipped : (int, int) -> int\n".to_string()} else {String::new()};
  for i in 0..100 {text.push_str(&format!("function f{n}_{i}() -> int = combine(1 + 2, 3)\n"));}
  change.change_file(id,text);
 }
 change.set_source_project(SourceProject { roots:ids.clone(),paths,modules:ModuleGraph{modules:vec![ModuleData{files:ids,requires:vec![]}],globals:vec![]},..Default::default() });
 host.apply_change(change);
 let files=host.raw_database().files().clone();
 let reverse=urls.iter().map(|(u,id)|(*id,u.clone())).collect();
 let analysis=Analysis::with_include_graph(host.raw_database().clone(),files,UrlMap::new(urls,reverse),std::sync::Arc::new(hir::include_graph::IncludeGraph::default()));
 let mut samples=Vec::new();
 for _ in 0..12 {
  let now=Instant::now();
  let change=analysis.structural_search_replace(FileId::from_raw(0),ide_db::LineCol{line:2,col:29},"combine($a, $b) ==>> flipped($b, $a)",false,&[],&HashSet::new()).unwrap().unwrap();
  let us=now.elapsed().as_micros();
  let mut entries:Vec<_>=change.source_file_edits.iter().collect(); entries.sort_by_key(|(id,_)|**id);
  let mut hash=std::collections::hash_map::DefaultHasher::new();let mut count=0;
  for (id,edits) in entries {id.hash(&mut hash); for e in edits {e.range.hash(&mut hash);e.new_text.hash(&mut hash);count+=1;}}
  assert_eq!(count,1000);
  samples.push(serde_json::json!({"us":us,"edits":count,"digest":hash.finish()}));
 }
 println!("{}",serde_json::json!(samples));
}

semantic_prefilter.probe:
use ide_db::{root_database::RootDatabase, apply_change::Change};
fn main() {
    tracing_subscriber::fmt().with_ansi(false).with_max_level(tracing::Level::INFO).with_span_events(tracing_subscriber::fmt::format::FmtSpan::NEW).init();
    for _ in 0..5 {
        let mut source = String::from("struct S = { x : int, enabled : bool }\n");
        for i in 0..200 {
            source.push_str(&format!("function unused_{i}() -> int = 1\n"));
        }
        let start = source.len() + "function target() -> S = ".len();
        source.push_str("function target() -> S = struct S { x = 1 }\n");
        let end = source.len() - 1;
        let id = base_db::FileId::from_raw(0);
        let mut db = RootDatabase::default();
        let mut change = Change::new();
        change.change_file(id, source);
        db.apply_change(change);
        let ft = db.files().file_text(id).unwrap();
        let sema = hir::Semantics::new(&db);
        let now = std::time::Instant::now();
        let fields = sema.missing_record_fields(ft, base_db::text_range(start,end));
        assert_eq!(fields, Some(vec![("enabled".into(), "bool".into())]));
        println!("cold_query_ms={:.3}",now.elapsed().as_secs_f64()*1000.0);
    }
}
